UTC = timezone.utc


def read_text(path):
    with open(path, 'rb') as f:
        data = f.read()
    if data[:2] == b'\x1f\x8b':
        data = gzip.decompress(data)
    return data.decode('utf-8-sig').replace('\r\n', '\n').replace('\r', '\n')


def lines_of(path):
    return [l for l in read_text(path).split('\n') if l.strip() != '']


def files_in(d):
    out = []
    if os.path.isdir(d):
        for root, _, fs in os.walk(d):
            for f in fs:
                out.append(os.path.join(root, f))
    return sorted(out)


def local_to_epoch(naive, zone, abbr=None):
    """naive local datetime -> epoch seconds. Ambiguous: abbr decides, else first."""
    a = naive.replace(tzinfo=zone, fold=0)
    b = naive.replace(tzinfo=zone, fold=1)
    if a.utcoffset() != b.utcoffset():
        if abbr:
            dst = abbr.strip().upper().endswith('DT')
            # fold=0 is the daylight (earlier) occurrence when clocks go back
            if a.dst() and not b.dst():
                return int((a if dst else b).timestamp())
            if b.dst() and not a.dst():
                return int((b if dst else a).timestamp())
        return int(a.timestamp())
    return int(a.timestamp())


def std_offset(zone):
    # standard (non-DST) offset in seconds
    for m in (1, 7, 4, 10):
        d = datetime(2026, m, 15, 12, tzinfo=zone)
        if not d.dst():
            return int(d.utcoffset().total_seconds())
    d = datetime(2026, 1, 15, 12, tzinfo=zone)
    return int((d.utcoffset() - d.dst()).total_seconds())


def parse_abbr(path, zone, site):
    out = []
    header = None
    for line in lines_of(path):
        row = next(csv.reader([line]))
        row = [c.strip() for c in row]
        if 'Badge' in row and 'Punch' in row and 'Time' in row:
            header = row
            continue
        if header is None:
            continue
        r = dict(zip(header, row))
        t = r['Time'].strip()
        ampm = None
        up = t.upper()
        if up.endswith('AM') or up.endswith('PM'):
            ampm = up[-2:]
            t = t[:-2].strip()
        h, m, s = [int(x) for x in t.split(':')]
        if ampm:
            h = h % 12 + (12 if ampm == 'PM' else 0)
        mo, d, y = [int(x) for x in r['Date'].split('/')]
        naive = datetime(y, mo, d, h, m, s)
        ep = local_to_epoch(naive, zone, r.get('Zone'))
        out.append((r['Record'], r['Badge'], r['Punch'].upper(), ep))
    return out


def parse_epoch(path):
    out = []
    schema = 1
    for line in lines_of(path):
        o = json.loads(line)
        if not isinstance(o, dict):
            continue
        if 'schema' in o and 'heartbeat' not in o:
            schema = o['schema']
            continue
        if o.get('heartbeat'):
            continue
        if schema == 2:
            pid, emp, d, ms = o.get('punch_id'), o.get('employee'), o.get('direction'), o.get('epoch_ms')
            ep = int(ms // 1000)
        else:
            pid, emp, d = o.get('id'), o.get('emp'), o.get('dir')
            if 'ts_ms' in o:
                ep = int(o['ts_ms'] // 1000)
            else:
                ep = int(o['ts'] // 1)
        if pid is None or emp is None or d is None:
            continue
        out.append((str(pid), emp, d.upper(), ep))
    return out


def parse_offset(path):
    out = []
    text = read_text(path)
    rows = list(csv.reader(io.StringIO(text), delimiter=';', quotechar='"'))
    header = None
    for row in rows:
        if not row or all(c.strip() == '' for c in row):
            continue
        if 'punch_id' in row and 'timestamp' in row:
            header = row
            continue
        if header is None:
            continue
        r = dict(zip(header, row))
        ts = datetime.fromisoformat(r['timestamp'].strip())
        d = 'IN' if r['event'].strip().lower() == 'clock_in' else 'OUT'
        out.append((r['punch_id'].strip(), r['employee'].strip(), d, int(ts.timestamp())))
    return out


def parse_legacy(path, zone):
    out = []
    std = std_offset(zone)
    cur = std
    for line in lines_of(path):
        t = line[0]
        if t == 'H':
            off = line[13:18].strip()
            if len(off) == 5 and off[0] in '+-':
                v = (int(off[1:3]) * 3600 + int(off[3:5]) * 60)
                cur = v if off[0] == '+' else -v
            else:
                cur = std
        elif t == 'D':
            pid = line[1:9]
            badge = line[9:15].strip()
            d = 'IN' if line[15] == 'I' else 'OUT'
            dt = line[16:30]
            naive = datetime(int(dt[0:4]), int(dt[4:6]), int(dt[6:8]), int(dt[8:10]), int(dt[10:12]), int(dt[12:14]))
            ep = int(naive.replace(tzinfo=UTC).timestamp()) - cur
            out.append((pid, 'E' + badge, d, ep))
    return out


def parse_de(path, zone):
