    header = None
    for line in lines_of(path):
        row = [c.strip() for c in line.split('\t')]
        if 'Ausweis' in row and 'Buchung' in row:
            header = row
            continue
        if header is None:
            continue
        r = dict(zip(header, row))
        dd, mm, yy = [int(x) for x in r['Datum'].split('.')]
        hh, mi = [int(x) for x in r['Uhrzeit'].split(':')[:2]]
        naive = datetime(yy, mm, dd, hh, mi)
        abbr = 'DT' if r.get('Zeitzone', '').upper() == 'MESZ' else 'ST'
        ep = local_to_epoch(naive, zone, abbr)
        out.append((r['Nr'], r['Ausweis'], 'IN' if r['Buchung'].upper() == 'K' else 'OUT', ep))
    return out


def parse_local_csv(path, zone):
