        if 'employee_id' in row and 'local_time' in row:
            header = row
            continue
        if header is None:
            continue
        r = dict(zip(header, row))
        naive = datetime.strptime(r['local_time'], '%Y-%m-%d %H:%M:%S')
        out.append((r['punch_ref'], r['employee_id'], r['direction'].upper(), local_to_epoch(naive, zone)))
    return out


def parse_local_jsonl(path, zone):
    out = []
    for line in lines_of(path):
        o = json.loads(line)
        p = o.get('punch') if isinstance(o, dict) else None
        if not isinstance(p, dict):
            continue
        naive = datetime.strptime(p['at'], '%Y-%m-%d %H:%M:%S')
        pid = p['id']
        pid = str(int(pid)) if isinstance(pid, (int, float)) else str(pid).strip()
        out.append((pid, p['badge'], p['type'].upper(), local_to_epoch(naive, zone)))
    return out


def round_epoch(ep, zone):
    off = int(datetime.fromtimestamp(ep, zone).utcoffset().total_seconds())
    loc = ep + off
    r = ((loc + 180) // 360) * 360
    return r - off


