                (date.fromisoformat(r['effective_from'].strip()), Fraction(r['hourly_rate'].strip())))
    for v in rates.values():
        v.sort()

    # 1. collect
    punches = {}  # (site,id) -> [emp, dir, epoch]
    ever = set()
    for site, (zone, fmt) in sites.items():
        for path in files_in(os.path.join(indir, 'exports', site)):
            if fmt == 'abbr-csv':
                recs = parse_abbr(path, zone, site)
            elif fmt == 'epoch-jsonl':
                recs = parse_epoch(path)
            elif fmt == 'offset-csv':
                recs = parse_offset(path)
            elif fmt == 'legacy-fixed':
                recs = parse_legacy(path, zone)
            elif fmt == 'de-tsv':
                recs = parse_de(path, zone)
            elif fmt == 'local-csv':
                recs = parse_local_csv(path, zone)
            elif fmt == 'local-jsonl':
                recs = parse_local_jsonl(path, zone)
            else:
                raise SystemExit('unknown format ' + fmt)
            for pid, emp, d, ep in recs:
                key = (site, pid)
                ever.add(key)
                if key not in punches:
                    punches[key] = [emp.strip(), d, ep]

    # 2. corrections
    corr = []
    for path in files_in(os.path.join(indir, 'corrections')):
        text = read_text(path)
        for r in csv.DictReader(io.StringIO(text)):
            if not r.get('correction_id'):
                continue
            corr.append(r)
    keyed = []
    for r in corr:
        ia = datetime.fromisoformat(r['issued_at'].strip().replace('Z', '+00:00'))
        if ia > cutoff:
            continue
        keyed.append((ia, r['correction_id'], r))
    keyed.sort(key=lambda x: (x[0], x[1]))
    applied = 0
    for _, _, r in keyed:
        act = r['action'].strip().lower()
        key = (r['site'].strip(), r['punch_id'].strip())
        if act == 'void':
            if key in punches:
                del punches[key]
                applied += 1
        elif act == 'set':
            if key in punches:
                punches[key][2] = int(datetime.fromisoformat(r['time'].strip()).timestamp())
                applied += 1
        elif act == 'add':
            if key not in ever and key[0] in sites:
                punches[key] = [r['employee'].strip(), r['type'].strip().upper(),
                                int(datetime.fromisoformat(r['time'].strip()).timestamp())]
                ever.add(key)
                applied += 1

    byemp = {}
    for (site, pid), (emp, d, ep) in punches.items():
        if emp in employees:
            byemp.setdefault(emp, []).append((ep, 0 if d == 'OUT' else 1, site, pid, d))

    counts = {'open_shifts': 0, 'orphan_outs': 0, 'duplicates_dropped': 0, 'corrections_applied': applied}
    res = {e: {'shifts': 0, 'paid_minutes': 0, 'overtime_minutes': 0, 'night_minutes': 0, 'gross': Fraction(0)}
           for e in employees}

    def in_period(d):
        return pstart <= d <= pend

    for emp, lst in byemp.items():
        home = sites[employees[emp]][0]
        lst.sort()
        kept = []
        last = None
        for ep, _, site, pid, d in lst:
            zone = sites[site][0]
            rp = round_epoch(ep, zone)
            if last is not None and last[4] == d and ep - last[0] <= 300:
                wd = datetime.fromtimestamp(rp, home).date()
                if in_period(wd):
                    counts['duplicates_dropped'] += 1
                continue
            last = (ep, 0, site, pid, d)
            kept.append((rp, site, d))
        wday = lambda rp: datetime.fromtimestamp(rp, home).date()
        shifts = []
        pend_in = None
        for rp, site, d in kept:
            if d == 'IN':
                if pend_in is not None and in_period(wday(pend_in[0])):
                    counts['open_shifts'] += 1
                pend_in = (rp, site)
            else:
                if pend_in is not None and rp - pend_in[0] <= 16 * 3600:
                    shifts.append((pend_in[0], rp, pend_in[1]))
                    pend_in = None
                else:
                    if pend_in is not None and in_period(wday(pend_in[0])):
                        counts['open_shifts'] += 1
                    pend_in = None
                    if in_period(wday(rp)):
                        counts['orphan_outs'] += 1
        if pend_in is not None and in_period(wday(pend_in[0])):
            counts['open_shifts'] += 1

        shifts = [s for s in shifts if in_period(wday(s[0]))]
        shifts.sort(key=lambda s: s[0])
        daily_used = {}
        week_used = {}
        R = res[emp]
        for rin, rout, site in shifts:
            zone = sites[site][0]
            wd = wday(rin)
            worked = max(0, (rout - rin) // 60)
            paid = worked - 30 if worked > 360 else worked
            # night
            night = 0
            cache = {}
            t = rin
            while t < rout:
                k = t // 900
                if k not in cache:
                    cache[k] = int(datetime.fromtimestamp(t, zone).utcoffset().total_seconds())
                lh = ((t + cache[k]) % 86400) // 3600
                if lh >= 22 or lh < 6:
                    night += 1
                t += 60
            night = min(night, paid)
            # overtime
            du = daily_used.get(wd, 0)
            reg_day = max(0, min(paid, 480 - du))
            dot = paid - reg_day
            daily_used[wd] = du + paid
            wk = wd - timedelta(days=wd.weekday())
            wu = week_used.get(wk, 0)
            nd = paid - dot
            wot = max(0, wu + nd - 2400) - max(0, wu - 2400)
            week_used[wk] = wu + nd
            ot = dot + wot
            reg = paid - ot
            r_list = rates.get(emp, [])
            rate = None
            for eff, v in r_list:
                if eff <= wd:
                    rate = v
            if rate is None:
                rate = r_list[0][1] if r_list else Fraction(0)
            pay = rate * (reg + Fraction(3, 2) * ot) / 60 + rate * Fraction(15, 100) * night / 60
            R['shifts'] += 1
            R['paid_minutes'] += paid
            R['overtime_minutes'] += ot
            R['night_minutes'] += night
            R['gross'] += pay

    def money(fr):
        cents = int((fr * 100 + Fraction(1, 2)) // 1)
        return '%d.%02d' % (cents // 100, cents % 100)

    out_emps = {}
    tot = {'shifts': 0, 'paid_minutes': 0, 'overtime_minutes': 0, 'night_minutes': 0}
    totc = 0
    for e, R in res.items():
        g = money(R['gross'])
        totc += int(g.replace('.', ''))
        out_emps[e] = {k: R[k] for k in tot}
        out_emps[e]['gross'] = g
        for k in tot:
            tot[k] += R[k]
    tot['gross'] = '%d.%02d' % (totc // 100, totc % 100)
    result = {'period': {'start': period['start'], 'end': period['end']},
              'employees': out_emps, 'exceptions': counts, 'totals': tot}
    with open(outfile, 'w') as f:
        json.dump(result, f, indent=1)


if __name__ == '__main__':
    main(sys.argv[1], sys.argv[2])
